def _record(
    language: str,
    mode: str,
    turns: Iterable[tuple[str, str]],
    response: str,
    flirt_level: str = "none",
) -> dict[str, object]:
    return {
        "messages": [
            {"role": "system", "content": RU_SYSTEM_PROMPT},
            *({"role": role, "content": content} for role, content in turns),
        ],
        "response": response,
        "language": language,
        "mode": mode,
        "source": SOURCE,
        "license": LICENSE,
        "flirt_level": flirt_level,
    }


def _entry(
    language: str,
    mode: str,
    prompt: str,
    response: str,
    *,
    flirt_level: str = "none",
    history: tuple[tuple[str, str], ...] = (),
) -> dict[str, object]:
    return _record(language, mode, (*history, ("user", prompt)), response, flirt_level)


