def v7_dialogue_records() -> list[dict[str, object]]:
    rows = [*_vietnamese_rows(), *_english_rows(), *_mixed_rows()]
    if len(rows) != V7_TOTAL_ROWS:
        raise ValueError(f"V7 dialogue source must contain {V7_TOTAL_ROWS} rows, found {len(rows)}")
    return rows
